  `middle_name` varchar(80) DEFAULT NULL,
  `last_name` varchar(80) NOT NULL,
  `second_last_name` varchar(80) DEFAULT NULL,
  `national_id` varchar(30) NOT NULL,
  `promotion_type` enum('OFICIAL','TROPA') NOT NULL,
  `promotion_number` varchar(30) DEFAULT NULL,
  `email` varchar(150) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `national_directorate_id` bigint(20) unsigned NOT NULL,
  `zone_id` bigint(20) unsigned DEFAULT NULL,
  `area_id` bigint(20) unsigned DEFAULT NULL,
  `service_id` bigint(20) unsigned NOT NULL,
  `card_condition` varchar(50) NOT NULL,
  `barcode_value` varchar(120) DEFAULT NULL,
  `barcode_readable` tinyint(1) NOT NULL DEFAULT 1,
  `card_front_path` varchar(255) DEFAULT NULL,
  `card_back_path` varchar(255) DEFAULT NULL,
  `person_with_card_path` varchar(255) DEFAULT NULL,
  `loss_report_number` varchar(80) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'RECIBIDA',
  `admin_observation` text DEFAULT NULL,
  `submitted_at` datetime NOT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `reviewed_by` varchar(120) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(500) DEFAULT NULL,
  `card_expiration_date` date DEFAULT NULL,
  `institutional_unit_id` bigint(20) unsigned DEFAULT NULL,
  `exact_work_location` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `request_number` (`request_number`),
  UNIQUE KEY `position_number` (`position_number`),
  UNIQUE KEY `national_id` (`national_id`),
  UNIQUE KEY `uq_barcode` (`barcode_value`),
  KEY `idx_request_directorate` (`national_directorate_id`),
  KEY `idx_request_zone` (`zone_id`),
  KEY `idx_request_area` (`area_id`),
  KEY `idx_request_service` (`service_id`),
  CONSTRAINT `fk_request_area` FOREIGN KEY (`area_id`) REFERENCES `organizational_units` (`id`),
  CONSTRAINT `fk_request_directorate` FOREIGN KEY (`national_directorate_id`) REFERENCES `organizational_units` (`id`),
  CONSTRAINT `fk_request_service` FOREIGN KEY (`service_id`) REFERENCES `organizational_units` (`id`),
  CONSTRAINT `fk_request_zone` FOREIGN KEY (`zone_id`) REFERENCES `organizational_units` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
